use std::io::{self,Read};use olp_rust::{json::{self,Json},CAPABILITIES};
fn response_ok(output:Json)->Json{let mut m=Json::object();m.insert("protocol".into(),Json::String("olp-conformance-adapter-v1".into()));m.insert("ok".into(),Json::Bool(true));m.insert("output".into(),output);Json::Object(m)}
fn response_err(classification:&str,reason:&str,message:&str)->Json{let mut e=Json::object();e.insert("classification".into(),Json::String(classification.into()));e.insert("reason".into(),Json::String(reason.into()));e.insert("message".into(),Json::String(message.into()));let mut m=Json::object();m.insert("protocol".into(),Json::String("olp-conformance-adapter-v1".into()));m.insert("ok".into(),Json::Bool(false));m.insert("error".into(),Json::Object(e));Json::Object(m)}
fn main(){let mut raw=String::new();io::stdin().read_to_string(&mut raw).unwrap();let lines:Vec<&str>=raw.lines().filter(|l|!l.trim().is_empty()).collect();let response=if lines.len()!=1{response_err("MALFORMED","REQUEST_COUNT","expected exactly one request")}else{match json::parse(lines[0]){Err(e)=>response_err("MALFORMED","MALFORMED_INPUT",&e),Ok(req)=>{let obj=match req.as_object(){Ok(v)=>v,Err(e)=>{println!("{}",json::stringify(&response_err("MALFORMED","MALFORMED_INPUT",&e)));return}};let protocol=obj.get("protocol").and_then(|v|v.as_str().ok()).unwrap_or("");if protocol!="olp-conformance-adapter-v1"{response_err("MALFORMED","PROTOCOL_MISMATCH","protocol mismatch")}else{let op=obj.get("operation").and_then(|v|v.as_str().ok()).unwrap_or("");if op=="capabilities"{let mut o=Json::object();o.insert("capabilities".into(),Json::Array(CAPABILITIES.iter().map(|s|Json::String((*s).into())).collect()));response_ok(Json::Object(o))}else{let input=obj.get("input").cloned().unwrap_or(Json::Object(Json::object()));match olp_rust::execute(op,&input){Ok(v)=>response_ok(v),Err(e)=>response_err(e.classification,&e.reason,&e.message)}}}}}};println!("{}",json::stringify(&response));}
